<?php
namespace App\Http\Controllers\CRM; use App\Http\Controllers\Controller; use App\Models\{Guest,GuestNote,GuestPreference,GuestTag,MarketingConsent}; use Illuminate\Http\Request;
class GuestCrmController extends Controller {
 public function index(Request $r){$p=auth()->user()->property_id;$q=Guest::where('property_id',$p)->with('loyaltyAccount.tier')->withCount(['reservations','complaints']);if($s=$r->q)$q->where(fn($x)=>$x->where('first_name','like',"%$s%")->orWhere('last_name','like',"%$s%")->orWhere('phone','like',"%$s%")->orWhere('email','like',"%$s%"));return view('crm.guests',['guests'=>$q->latest()->paginate(25)]);}
 public function show(Guest $guest){abort_unless($guest->property_id===auth()->user()->property_id,403);$guest->load(['loyaltyAccount.tier','loyaltyAccount.transactions'=>fn($q)=>$q->latest()->limit(20),'crmPreferences','crmNotes'=>fn($q)=>$q->latest(),'tags','feedback'=>fn($q)=>$q->latest(),'complaints'=>fn($q)=>$q->latest(),'marketingConsents','reservations'=>fn($q)=>$q->latest()->limit(15)]);return view('crm.guest-show',compact('guest'));}
 public function preference(Request $r,Guest $guest){abort_unless($guest->property_id===auth()->user()->property_id,403);$d=$r->validate(['category'=>'required|string|max:60','preference'=>'required|string|max:255','notes'=>'nullable|string','is_sensitive'=>'nullable|boolean']);$guest->crmPreferences()->create($d);return back()->with('success','Guest preference added.');}
 public function note(Request $r,Guest $guest){abort_unless($guest->property_id===auth()->user()->property_id,403);$d=$r->validate(['type'=>'required|string|max:40','note'=>'required|string','is_private'=>'nullable|boolean']);$d+=['property_id'=>$guest->property_id,'created_by'=>auth()->id()];$guest->crmNotes()->create($d);return back()->with('success','CRM note added.');}
 public function consent(Request $r,Guest $guest){abort_unless($guest->property_id===auth()->user()->property_id,403);$d=$r->validate(['channel'=>'required|in:email,sms,whatsapp,push','consented'=>'required|boolean']);MarketingConsent::updateOrCreate(['guest_id'=>$guest->id,'channel'=>$d['channel']],['consented'=>$d['consented'],'consented_at'=>$d['consented']?now():null,'withdrawn_at'=>$d['consented']?null:now(),'source'=>'staff']);return back()->with('success','Marketing consent updated.');}
}
